{
  "name": "Agilent/Keysight 33220A 函数/任意波形发生器",
  "name_en": "Agilent/Keysight 33220A Function/Arbitrary Waveform Generator",
  "manufacturer": "Agilent Technologies / Keysight Technologies",
  "description": "这是一款 20 MHz 台式函数/任意波形发生器，可输出常见测试波形并调节频率、相位、占空比、负载与输出极性等参数，常用于电子电路测试、信号激励、教学实验和通用实验室信号源应用。",
  "description_en": "This is a 20 MHz benchtop function/arbitrary waveform generator used to produce common test waveforms with adjustable frequency, phase, duty cycle, load setting, and output polarity. It is commonly used for electronic circuit testing, signal stimulation, teaching labs, and general laboratory signal-source applications.",
  "tag_hints": [
    "function generator",
    "arbitrary waveform generator",
    "20 MHz signal source",
    "electronic circuit testing",
    "waveform output",
    "phase control",
    "duty cycle control"
  ],
  "actions": [
    {
      "action_name": "auto-duty_cycle",
      "description": "获取/设置/定义输出波形的占空比",
      "description_en": "Get/set/define the duty cycle of the output waveform."
    },
    {
      "action_name": "auto-function",
      "description": "获取/设置/定义输出波形类型",
      "description_en": "Get/set/define the output waveform function."
    },
    {
      "action_name": "auto-load_resistance",
      "description": "获取/设置/定义输出端的终端负载电阻",
      "description_en": "Get/set/define the output termination load resistance."
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置/定义输出开关状态",
      "description_en": "Get/set/define the output enabled state."
    },
    {
      "action_name": "auto-output_polarity",
      "description": "获取/设置/定义输出极性",
      "description_en": "Get/set/define the output polarity."
    },
    {
      "action_name": "auto-output_sync",
      "description": "获取/设置/定义同步输出开关状态",
      "description_en": "Get/set/define the sync output enabled state."
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置/定义输出相位",
      "description_en": "Get/set/define the output phase."
    },
    {
      "action_name": "auto-ramp_symmetry",
      "description": "获取/设置/定义斜坡波形的对称性",
      "description_en": "Get/set/define the symmetry of the ramp waveform."
    }
  ]
}

